
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbepow_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbepow", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.309618725053204e+00, -4.228256520192120e+00, -4.114404707712043e+00, -3.957025169784540e+00, -3.743295997813268e+00, -3.460420071272054e+00, -3.099867403347640e+00, -2.665201842792459e+00, -2.181850635525214e+00, -1.683763846523487e+00, -1.141347830649415e+00, -7.162961572075329e-01, -6.024744330766942e-01, -5.041892549941460e-01, -3.803109683211674e-01, -2.586780065048803e-01, -1.401256870551905e-01, -4.995681452088298e-02, -1.081664808243949e-02, -1.216209029773901e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


